def word_tokens(text: str | None) -> list[str]:
    """Split text into word tokens."""
    if not text:
        return []
    return _WORD_TOKEN_RE.findall(text)


def exact_text_key(text: str | None) -> tuple[str, ...]:
    """Keep word order and numbers while folding accents and punctuation."""
    if not text:
        return ()
    return tuple(word_tokens(normalize_ascii(text).lower().replace("_", " ")))


def has_branch_campus_specifier(text_norm: str) -> bool:
    """Return True if normalized text contains a branch or campus specifier."""
    tokens = set(word_tokens(text_norm))
    return (
        "co so" in text_norm
        or "phan hieu" in text_norm
        or "chi nhanh" in text_norm
        or "campus" in tokens
        or "cs" in tokens
        or any(tok.startswith("cs") and len(tok) >= 3 and tok[2:].isdigit() for tok in tokens)
